#include \"stream_pool.cuh\"\n#include <iostream>\n#include <chrono>\n#include <vector>\n#include <cuda_runtime.h>\n\n// Simple kernel for testing\n__global__ void test_kernel(float* data, int n, float value) {\n    int idx = blockIdx.x * blockDim.x + threadIdx.x;\n    if (idx < n) {\n        data[idx] += value;\n    }\n}\n\nvoid test_stream_pool() {\n    std::cout << \"Testing Stream Pool...\\n\";\n    \n    // Create stream pool\n    gpumap::stream::StreamPool pool(4);\n    \n    const int n = 1000000;\n    const size_t bytes = n * sizeof(float);\n    \n    // Allocate device memory\n    float *d_data1, *d_data2, *d_data3, *d_data4;\n    cudaMalloc(&d_data1, bytes);\n    cudaMalloc(&d_data2, bytes);\n    cudaMalloc(&d_data3, bytes);\n    cudaMalloc(&d_data4, bytes);\n    \n    // Initialize data\n    cudaMemset(d_data1, 0, bytes);\n    cudaMemset(d_data2, 0, bytes);\n    cudaMemset(d_data3, 0, bytes);\n    cudaMemset(d_data4, 0, bytes);\n    \n    auto start = std::chrono::high_resolution_clock::now();\n    \n    // Test 1: Sequential execution with default stream\n    {\n        std::cout << \"Sequential execution...\\n\";\n        \n        int threads = 256;\n        int blocks = (n + threads - 1) / threads;\n        \n        test_kernel<<<blocks, threads>>>(d_data1, n, 1.0f);\n        cudaDeviceSynchronize();\n        \n        test_kernel<<<blocks, threads>>>(d_data2, n, 2.0f);\n        cudaDeviceSynchronize();\n        \n        test_kernel<<<blocks, threads>>>(d_data3, n, 3.0f);\n        cudaDeviceSynchronize();\n        \n        test_kernel<<<blocks, threads>>>(d_data4, n, 4.0f);\n        cudaDeviceSynchronize();\n    }\n    \n    auto sequential_time = std::chrono::high_resolution_clock::now();\n    \n    // Reset data\n    cudaMemset(d_data1, 0, bytes);\n    cudaMemset(d_data2, 0, bytes);\n    cudaMemset(d_data3, 0, bytes);\n    cudaMemset(d_data4, 0, bytes);\n    \n    // Test 2: Parallel execution with stream pool\n    {\n        std::cout << \"Parallel execution with stream pool...\\n\";\n        \n        gpumap::stream::MultiStreamExecutor<std::function<void(cudaStream_t)>> executor(pool);\n        \n        int threads = 256;\n        int blocks = (n + threads - 1) / threads;\n        \n        executor.add_task([=](cudaStream_t stream) {\n            test_kernel<<<blocks, threads, 0, stream>>>(d_data1, n, 1.0f);\n        });\n        \n        executor.add_task([=](cudaStream_t stream) {\n            test_kernel<<<blocks, threads, 0, stream>>>(d_data2, n, 2.0f);\n        });\n        \n        executor.add_task([=](cudaStream_t stream) {\n            test_kernel<<<blocks, threads, 0, stream>>>(d_data3, n, 3.0f);\n        });\n        \n        executor.add_task([=](cudaStream_t stream) {\n            test_kernel<<<blocks, threads, 0, stream>>>(d_data4, n, 4.0f);\n        });\n        \n        executor.execute_all();\n    }\n    \n    auto parallel_time = std::chrono::high_resolution_clock::now();\n    \n    // Calculate timings\n    auto seq_duration = std::chrono::duration_cast<std::chrono::milliseconds>(\n        sequential_time - start).count();\n    auto par_duration = std::chrono::duration_cast<std::chrono::milliseconds>(\n        parallel_time - sequential_time).count();\n    \n    std::cout << \"Sequential time: \" << seq_duration << \" ms\\n\";\n    std::cout << \"Parallel time: \" << par_duration << \" ms\\n\";\n    std::cout << \"Speedup: \" << (double)seq_duration / par_duration << \"x\\n\";\n    \n    // Test 3: RAII stream usage\n    {\n        std::cout << \"Testing RAII stream usage...\\n\";\n        \n        // Multiple scoped stream usage\n        for (int i = 0; i < 8; ++i) {\n            gpumap::stream::StreamGuard guard(pool);\n            auto stream = guard.get();\n            \n            int threads = 256;\n            int blocks = (n + threads - 1) / threads;\n            \n            test_kernel<<<blocks, threads, 0, stream>>>(d_data1, n, 0.1f);\n            cudaStreamSynchronize(stream);\n            \n            std::cout << \"Task \" << i << \" completed on stream \" << stream << \"\\n\";\n        }\n    }\n    \n    // Cleanup\n    cudaFree(d_data1);\n    cudaFree(d_data2);\n    cudaFree(d_data3);\n    cudaFree(d_data4);\n    \n    std::cout << \"Stream pool test completed!\\n\";\n}\n\nint main() {\n    // Check CUDA device\n    int device_count;\n    cudaGetDeviceCount(&device_count);\n    \n    if (device_count == 0) {\n        std::cout << \"No CUDA devices found!\\n\";\n        return 1;\n    }\n    \n    std::cout << \"Found \" << device_count << \" CUDA device(s)\\n\";\n    \n    // Set device and run test\n    cudaSetDevice(0);\n    test_stream_pool();\n    \n    return 0;\n}